from __future__ import annotations

import uuid
from dataclasses import dataclass
from datetime import date, datetime
from decimal import Decimal
from enum import StrEnum


class TransactionType(StrEnum):
    EXPENSE = "expense"
    INCOME = "income"


class TransactionSource(StrEnum):
    # Registered by the user, conversing.
    MANUAL = "manual"
    # Generated by the system: by a recurring rule, which recurring_rule_id tells apart, or
    # detected in a notice email (docs/03-modelo-de-datos.md).
    AUTOMATIC = "automatic"


@dataclass(frozen=True)
class Transaction:
    """An expense or an income already confirmed, with what the balance of its account needs.

    The amount is in the currency it was made in. When that is not the currency of its
    account, `exchange_rate` says how many units of the other currency one unit is worth.
    """

    id: uuid.UUID
    user_id: uuid.UUID
    account_id: uuid.UUID
    type: TransactionType
    amount: Decimal
    currency: str
    exchange_rate: Decimal | None
    transaction_date: date
    # Set when it describes the same money as another movement: then it counts nowhere.
    duplicate_of: uuid.UUID | None = None
    deleted_at: datetime | None = None
    # What a balance does not need, and a new movement always has. Reading for a balance
    # leaves them out.
    budget_period_id: uuid.UUID | None = None
    category_id: uuid.UUID | None = None
    source: TransactionSource | None = None
    description: str | None = None
